#!/usr/bin/env python3
"""Minimal Go board helper for authoring tsumego. Not part of the submission."""

from __future__ import annotations

COLS = "abcdefghijklmnopqrs"


def coord(s: str) -> tuple[int, int]:
    return COLS.index(s[0]), COLS.index(s[1])


def name(x: int, y: int) -> str:
    return COLS[x] + COLS[y]


def neighbors(x: int, y: int):
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nx, ny = x + dx, y + dy
        if 0 <= nx < 19 and 0 <= ny < 19:
            yield nx, ny


class Board:
    def __init__(self):
        self.g = [[None] * 19 for _ in range(19)]

    def copy(self) -> "Board":
        b = Board()
        b.g = [row[:] for row in self.g]
        return b

    def place_setup(self, black: list[str], white: list[str]):
        for s in black:
            x, y = coord(s)
            if self.g[y][x] is not None:
                raise ValueError(f"double setup {s}")
            self.g[y][x] = "B"
        for s in white:
            x, y = coord(s)
            if self.g[y][x] is not None:
                raise ValueError(f"double setup {s}")
            self.g[y][x] = "W"

    def group(self, x: int, y: int):
        color = self.g[y][x]
        if color is None:
            return set(), set()
        stones = set()
        libs = set()
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in stones:
                continue
            stones.add((cx, cy))
            for nx, ny in neighbors(cx, cy):
                v = self.g[ny][nx]
                if v is None:
                    libs.add((nx, ny))
                elif v == color and (nx, ny) not in stones:
                    stack.append((nx, ny))
        return stones, libs

    def play(self, color: str, s: str) -> int:
        x, y = coord(s)
        if self.g[y][x] is not None:
            raise ValueError(f"occupied {s}")
        self.g[y][x] = color
        opp = "W" if color == "B" else "B"
        captured = 0
        for nx, ny in neighbors(x, y):
            if self.g[ny][nx] == opp:
                stones, libs = self.group(nx, ny)
                if not libs:
                    for sx, sy in stones:
                        self.g[sy][sx] = None
                    captured += len(stones)
        stones, libs = self.group(x, y)
        if not libs:
            self.g[y][x] = None
            raise ValueError(f"suicide {s}")
        return captured

    def strings(self):
        seen = set()
        out = []
        for y in range(19):
            for x in range(19):
                if self.g[y][x] and (x, y) not in seen:
                    stones, libs = self.group(x, y)
                    seen |= stones
                    out.append((self.g[y][x], [name(a, b) for a, b in sorted(stones)], [name(a, b) for a, b in sorted(libs)]))
        return out

    def dump(self, x0=0, y0=0, x1=18, y1=18) -> str:
        rows = ["   " + " ".join(COLS[x] for x in range(x0, x1 + 1))]
        for y in range(y0, y1 + 1):
            cells = []
            for x in range(x0, x1 + 1):
                v = self.g[y][x]
                cells.append("X" if v == "B" else "O" if v == "W" else ".")
            rows.append(f"{COLS[y]}  " + " ".join(cells))
        return "\n".join(rows)


def parse_list(s: str):
    return [p for p in s.replace("[", " ").replace("]", " ").split() if p]


if __name__ == "__main__":
    # Problem 1 draft
    b = Board()
    AB = parse_list("aq ar bq cq cr")
    AW = parse_list("ap as bp co cp do dp dq dr ds eo ep er fr fp fq")
    b.place_setup(AB, AW)
    print("P1 setup")
    print(b.dump(0, 14, 6, 18))
    print("strings", b.strings())
    b1 = b.copy()
    print("B[bs] captured", b1.play("B", "bs"))
    print(b1.dump(0, 14, 6, 18))
    print("strings after B[bs]", b1.strings())

